SELECT si.code, si.order_type AS orderType, si.approve_status AS approveStatus, si.customer_id AS customerId, si.invalid_status AS invalidStatus, si.sales_org_name AS salesOrgName, si.seller_name AS sellerName, sod.delivery_status AS deliveryStatus, si.require_date AS requireDate, si.create_user_name AS createUserName, si.create_time AS createTime, si.warehouse_id AS warehouseId, si.receive_amount AS receiveAmount, si.id,sod.id AS detailId, si.approve_user_name AS approveUserName, si.approve_time AS approveTime, si.sales_dept_id AS salesDeptId, si.all_amount_lc AS allAmountLc, si.remark, si.customer_order_no AS customerOrderNo, sod.sku_id AS skuId, sod.sku_no AS skuNo, sod.qty, sod.amount, sod.currency, sod.currency_symbol AS currencySymbol, sod.price, sod.tax_amount AS taxAmount, sod.tax_rate AS taxRate, sod.remark as detailRemark, ci.country_id as countryId, sod.exchange_rate AS exchangeRate, sod.amount_local_currency AS amountLocalCurrency, sod.all_amount_local_currency AS allAmountLocalCurrency FROM so_info si LEFT JOIN so_detail sod ON sod.main_id =si.id AND si.is_deleted=false left join customer_info ci on si.customer_id = ci.id and ci.is_deleted = false WHERE sod.is_deleted=false
AND sod.sku_no IN
#{skuNo}
AND si.id IN
#{soId}
AND si.code ILIKE concat('%', #{params.code} ,'%')
AND si.customer_order_no ILIKE concat('%', #{params.customerOrderNo} ,'%')
AND si.order_type=#{params.orderType}
AND si.approve_status IN
#{approveStatus}
AND si.customer_id IN
#{customerId}
AND ci.country_id IN
#{item}
AND si.seller_id IN
#{sellerId}
AND si.invalid_status=#{params.invalidStatus}
AND sod.delivery_status=#{params.deliveryStatus}
AND si.create_user_id IN
#{createUserId}
AND si.approve_time >= #{params.approveTimeList[0]} and (#{params.approveTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > si.approve_time
AND si.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > si.create_time
AND si.require_date >= #{params.requireDateList[0]} and (#{params.requireDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > si.require_date
AND si.id IN
#{detailId}
AND (si.remark ILIKE concat('%', #{params.remark} ,'%') or sod.remark ILIKE concat('%', #{params.remark} ,'%'))
AND si.sales_org_id = #{params.salesOrgId}
AND si.sales_dept_id = #{params.salesDeptId}
AND ci.platform_type = #{params.platformType}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
si.create_time DESC,sod.id ASC

